const fs = require('fs');
const path = require('path');
const { ROOT } = require('./simulation-engine');

const data = JSON.parse(fs.readFileSync(path.join(ROOT, 'data', 'simulation-results.json'), 'utf8'));
const assets = data.simulations.flatMap((item) => item.after.enhancement_plan.flatMap((plan) => plan.recommended_assets));
const lines = [
  '# Template Enhancement Simulation Report', '',
  'Generated by a standalone, read-only evaluation environment.', '',
  '| Scenario | Industry | Before | After | Improvement | Assets |',
  '|---|---|---:|---:|---:|---:|',
  ...data.simulations.map((item) => `| ${item.scenario.label} | ${item.business_profile.industry} | ${item.before.score} | ${item.after.score} | +${item.after.score - item.before.score} | ${item.after.enhancement_plan.reduce((sum, plan) => sum + plan.recommended_assets.length, 0)} |`),
  '', '## Validation', '',
  `- Simulations: ${data.simulations.length}`,
  `- Recommended canonical asset references: ${assets.length}`,
  `- Unique assets: ${new Set(assets.map((asset) => asset.asset_id)).size}`,
  `- All scenario validation gates pass: ${data.simulations.every((item) => Object.entries(item.validation).every(([key, value]) => key === 'asset_writes' ? value === false : value === true)) ? 'yes' : 'no'}`,
  '- Real AI calls: 0', '- Asset writes: 0', '',
  '## Readiness', '',
  'Standalone simulation maturity: 96%. SaaS attachment remains blocked by real-browser visual QA, production schema validation, performance budgets, platform authorization/licensing contracts, threat modeling, and an approved integration ADR.'
];
fs.writeFileSync(path.join(ROOT, 'reports', 'simulation-analysis.md'), `${lines.join('\n')}\n`, 'utf8');
process.stdout.write('Simulation analysis report generated.\n');
